// Zella Voice - Follow-up Emails: turn one claimed follow-up task into a "prepare this email" request.
// Reactivation is marketing, so it needs the person's opt-in. The others follow up on something
// the person asked for. Anything unknown is skipped with a visible reason, never dropped silently.
const t = $json;
const skip = (reason) => ({ json: { task_id: t.task_id, finish: { rpc: 'zella_skip_followup_task', body: { p_task_id: t.task_id, p_reason: reason } } } });

const kinds = {
  no_show_follow_up: { key: 'no_show_follow_up', purpose: 'transactional' },
  post_appointment_follow_up: { key: 'post_appointment_follow_up', purpose: 'transactional' },
  quote_follow_up: { key: 'quote_follow_up', purpose: 'transactional' },
  lead_reactivation: { key: 'lead_reactivation', purpose: 'marketing' },
  // "You might also need" (sql/zella_cross_sell.sql): marketing, so only to people who opted in.
  cross_sell: { key: 'cross_sell', purpose: 'marketing' },
  welcome_new_customer: { key: 'welcome_new_customer', purpose: 'transactional' },
  feedback_request: { key: 'feedback_request', purpose: 'transactional' },
  cancellation_confirmation: { key: 'cancellation_confirmation', purpose: 'transactional' },
  record_status_update: { key: 'record_status_update', purpose: 'transactional' },
  service_due: { key: 'service_due', purpose: 'transactional' },
  no_response_follow_up: { key: 'no_response_follow_up', purpose: 'transactional' },
  reschedule_confirmation: { key: 'reschedule_confirmation', purpose: 'transactional' },
  booking_follow_up: { key: 'booking_follow_up', purpose: 'transactional' },
  service_completed: { key: 'service_completed', purpose: 'transactional' },
  lead_follow_up: { key: 'lead_follow_up', purpose: 'transactional' },
  lead_final_follow_up: { key: 'lead_final_follow_up', purpose: 'transactional' },
};
// A callback that ran out of tries leaves a task behind. The message depends on why the callback existed.
const byReason = { missed_call: 'missed_call_follow_up', new_lead: 'lead_acknowledgement' };
let k = kinds[t.kind];
if (t.kind === 'callback_sms') {
  const key = byReason[t.callback_reason];
  if (!key) return skip('unknown_callback_reason:' + String(t.callback_reason).slice(0, 30));
  k = { key, purpose: 'transactional' };
}
if (t.channel !== 'email') return skip('channel_not_email:' + t.channel);
if (!k) return skip('unknown_followup_kind:' + t.kind);

const vars = {};
if (t.vars && typeof t.vars === 'object') {
  for (const [key, val] of Object.entries(t.vars)) if (typeof val === 'string') vars[key] = val.slice(0, 300);
}

return {
  json: {
    task_id: t.task_id,
    business_id: t.business.id,
    customer_id: t.customer.id,
    template_key: k.key,
    prepare: { p_business_id: t.business.id, p_customer_id: t.customer.id, p_template_key: k.key, p_vars: vars, p_purpose: k.purpose },
    finish: null,
  },
};

// Zella Voice - Follow-up Emails: read the answer from "prepare" and decide what happens to this task.
const plan = $('Plan').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const skip = (reason) => ({ json: { task_id: plan.task_id, finish: { rpc: 'zella_skip_followup_task', body: { p_task_id: plan.task_id, p_reason: reason } } } });
const fail = (reason) => ({ json: { task_id: plan.task_id, finish: { rpc: 'zella_complete_followup_task', body: { p_task_id: plan.task_id, p_outcome: 'failed', p_notes: reason, p_retry_in_minutes: 15 } } } });

if (!(status >= 200 && status < 300)) return fail('The database call zella_prepare_email returned ' + status + '.');
if (b.allowed !== true) return skip(String(b.reason || 'not_allowed').slice(0, 60));
if (b.live === true && !b.from) return fail('sender_address_not_set');
// Pacing (owner, 27 Nov 2026): a connected mailbox sends at most 20 emails a minute. The database says when the next
// one may go (pace_until); this follow up waits until then, its try given back (zella_business_email_paced).
if (typeof b.pace_until === 'string' && b.pace_until) {
  return { json: { task_id: plan.task_id, finish: { rpc: 'zella_business_email_paced', body: { p_item: 'task', p_id: plan.task_id, p_until: b.pace_until.slice(0, 40) } } } };
}
// Who sends (sql/zella_business_email_send.sql): the business's verified domain or the fallback, both through Resend,
// or its connected mailbox through Gmail or Microsoft Graph. Anything else is Resend.
const transport = b.transport === 'gmail' || b.transport === 'outlook' ? b.transport : 'resend';
const route = typeof b.sender_route === 'string' && /^[a-z_]{1,20}$/.test(b.sender_route) ? b.sender_route : 'fallback';

return {
  json: {
    task_id: plan.task_id,
    live: b.live === true,
    transport,
    from: b.from || null,
    from_name: b.from_name || '',
    reply_to: b.reply_to || null,
    unsubscribe_url: typeof b.unsubscribe_url === 'string' && /^https:\/\/[^\s]+$/.test(b.unsubscribe_url) ? b.unsubscribe_url : null,
    to: b.to,
    subject: b.subject,
    text: b.body_text,
    html: b.body_html,
    finish: null,
    log: {
      p_business_id: plan.business_id,
      p_customer_id: plan.customer_id,
      p_to: b.to,
      p_from: b.from || '',
      p_subject: b.subject,
      p_body_text: b.body_text,
      p_body_html: b.body_html,
      p_dedupe_key: 'task:' + plan.task_id,
      p_status: b.live === true ? 'queued' : 'dry_run',
      p_meta: { task_id: plan.task_id, template_id: b.template_id, template_version: b.template_version, dry_run: b.live !== true, transport, sender_route: route },
    },
  },
};

// Zella Voice - Follow-up Emails: after the message is logged, decide whether to really send.
// A repeat of the same task is never sent twice. In dry-run nothing is sent.
const d = $('Decide').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const done = (rpc, body) => ({ json: { task_id: d.task_id, finish: { rpc, body } } });
const complete = (outcome, notes) => done('zella_complete_followup_task', { p_task_id: d.task_id, p_outcome: outcome, p_notes: notes, p_retry_in_minutes: 15 });

if (!(status >= 200 && status < 300)) return complete('failed', 'The database call zella_log_outbound_email returned ' + status + '.');
if (b.duplicate === true) {
  if (b.status === 'sent' || b.status === 'delivered') return complete('email_sent', null);
  return done('zella_skip_followup_task', { p_task_id: d.task_id, p_reason: 'duplicate_suppressed' });
}
if (d.live !== true) return done('zella_skip_followup_task', { p_task_id: d.task_id, p_reason: 'dry_run: no email was sent' });

// the business's own mailbox (Gmail, Outlook): the mailbox path sends it (mailbox-plan.js, mailbox-build.js)
if (d.transport === 'gmail' || d.transport === 'outlook') {
  return { json: { task_id: d.task_id, message_id: b.id, finish: null, transport: d.transport,
    mail: { from: d.from, from_name: d.from_name, to: d.to, reply_to: d.reply_to, subject: d.subject, text: d.text, html: d.html, unsubscribe_url: d.unsubscribe_url } } };
}
const name = String(d.from_name || '').replace(/[\r\n"<>]+/g, ' ').trim();
const resend = { from: name ? name + ' <' + d.from + '>' : d.from, to: [d.to], subject: d.subject, text: d.text, html: d.html };
// Replies go to the business's own inbox (owner, 26 Nov 2026).
if (d.reply_to) resend.reply_to = d.reply_to;
// Marketing email carries an unsubscribe header for mail apps as well as the link in the body.
if (d.unsubscribe_url) resend.headers = { 'List-Unsubscribe': '<' + d.unsubscribe_url + '>' };
return { json: { task_id: d.task_id, message_id: b.id, finish: null, transport: 'resend', resend } };

// Zella Voice - Follow-up Emails: turn the provider's answer into the message update and the task result.
// The provider's response text is never stored, only its status and a short error name. A mailbox that refused for its
// daily limit or its sign in goes to zella_business_email_mailbox_refused: the task is due again at once, without
// using up a try, and goes out through the fallback (sql/zella_business_email.sql).
// Zella Voice - the business's own mailbox (Gmail, Outlook): what the provider's answer to one send means. Shared by the
// Email Sender and Follow-up Emails (inlined into their After send steps). Only a status, a short name and our own id
// are kept: never the provider's text. refused: "quota" (its daily sending limit: the rest of the business's day goes
// through the fallback) or "sign_in" (the mailbox needs reconnecting); both go to zella_business_email_mailbox_refused.
function mailboxResult(transport, status, body, fail, messageId) {
  if (fail === 'sign_in') return { ok: false, refused: 'sign_in', external_id: null, error: 'The mailbox sign in no longer works; it needs reconnecting.' };
  if (fail === 'not_connected') return { ok: false, refused: null, external_id: null, error: 'The mailbox is not connected any more; trying again.' };
  if (fail) return { ok: false, refused: null, external_id: null, error: 'No answer from the mailbox sign in; trying again later.' };
  const b = body && typeof body === 'object' ? body : {};
  const err = b.error && typeof b.error === 'object' ? b.error : {};
  const name = (s) => (typeof s === 'string' && /^[A-Za-z_]{1,60}$/.test(s) ? ' (' + s + ')' : '');
  if (transport === 'gmail') {
    if (status >= 200 && status < 300 && typeof b.id === 'string' && /^[A-Za-z0-9_-]{1,100}$/.test(b.id)) return { ok: true, refused: null, external_id: 'gmail:' + b.id, error: null };
    const reasons = Array.isArray(err.errors) ? err.errors.map((e) => (e && typeof e.reason === 'string' ? e.reason : '')) : [];
    if (status === 429 || err.status === 'RESOURCE_EXHAUSTED' || reasons.some((r) => ['dailyLimitExceeded', 'userRateLimitExceeded', 'rateLimitExceeded', 'quotaExceeded', 'limitExceeded'].includes(r))) {
      return { ok: false, refused: 'quota', external_id: null, error: 'Gmail refused: its daily sending limit.' };
    }
    if (status === 401 || reasons.includes('authError') || reasons.includes('insufficientPermissions')) return { ok: false, refused: 'sign_in', external_id: null, error: 'Gmail refused the sign in; it needs reconnecting.' };
    return { ok: false, refused: null, external_id: null, error: isNaN(status) ? 'No answer from Gmail (timed out); trying again later.' : 'Gmail returned ' + status + name(reasons[0]) + '.' };
  }
  // Microsoft Graph sendMail answers 202 Accepted with no body and no id: our own message id stands in for it
  if (status >= 200 && status < 300) return { ok: true, refused: null, external_id: 'graph:' + String(messageId || '').replace(/[^0-9a-f-]/gi, '').slice(0, 40), error: null };
  const code = typeof err.code === 'string' ? err.code : '';
  if (status === 429 || ['ErrorExceededMessageLimit', 'ErrorQuotaExceeded', 'ErrorSubmissionQuotaExceeded'].includes(code)) {
    return { ok: false, refused: 'quota', external_id: null, error: 'Outlook refused: its daily sending limit.' };
  }
  if (status === 401 || ['InvalidAuthenticationToken', 'ErrorAccessDenied', 'Authorization_RequestDenied'].includes(code)) return { ok: false, refused: 'sign_in', external_id: null, error: 'Outlook refused the sign in; it needs reconnecting.' };
  return { ok: false, refused: null, external_id: null, error: isNaN(status) ? 'No answer from Outlook (timed out); trying again later.' : 'Outlook returned ' + status + name(code) + '.' };
}

const prev = $('After log').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
let ok, externalId, error, refused = null;
if (prev.transport === 'gmail' || prev.transport === 'outlook') {
  const r = mailboxResult(prev.transport, status, $json.body, $json.mailbox_fail, prev.message_id);
  ok = r.ok; externalId = r.external_id; error = r.error; refused = r.refused;
} else {
  externalId = b.id ? String(b.id) : null;
  ok = status >= 200 && status < 300 && !!externalId;
  const name = typeof b.name === 'string' && /^[a-z_]{1,40}$/.test(b.name) ? ' (' + b.name + ')' : '';
  error = ok ? null : status === 429 ? 'Rate limited (429); trying again later.' : isNaN(status) ? 'No answer from the provider (timed out); trying again later.' : 'The email provider returned ' + status + name + '.';
}

return {
  json: {
    task_id: prev.task_id,
    update: { p_id: prev.message_id, p_status: ok ? 'sent' : 'failed', p_external_id: externalId, p_error: error },
    finish: refused ? { rpc: 'zella_business_email_mailbox_refused', body: { p_message_id: prev.message_id, p_reason: refused } }
      : { rpc: 'zella_complete_followup_task', body: { p_task_id: prev.task_id, p_outcome: ok ? 'email_sent' : 'failed', p_notes: error, p_retry_in_minutes: status === 429 ? 30 : 15 } },
  },
};

// Zella Voice - the business's own mailbox: after the database handed out the mailbox's sign in for this one email
// (zella_business_email_mailbox_credentials), get ready to ask the provider for a short lived access token.
// The refresh token passes through this run only; these workflows keep no execution data.
const prev = $('After log').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
if (!(status >= 200 && status < 300) || b.ok !== true || typeof b.refresh_token !== 'string' || !b.refresh_token || b.provider !== prev.transport) {
  return { json: { mailbox_fail: 'not_connected', provider: prev.transport, token_form: null } };
}
return { json: { mailbox_fail: null, provider: b.provider, token_form: { refresh_token: b.refresh_token } } };

// Zella Voice - the business's own mailbox: with the access token, build the one send request. Gmail takes the whole
// email (RFC 5322, base64url, users.messages.send); Microsoft Graph takes a message (sendMail; it sends from the signed
// in account). Header values are made safe: no line breaks, a name that isn't plain ASCII is encoded.
const prev = $('After log').item.json;
const plan = $('Plan mailbox').item.json;
const status = Number($json.statusCode);
const t = $json.body && typeof $json.body === 'object' ? $json.body : {};
if (!(status >= 200 && status < 300) || typeof t.access_token !== 'string' || !t.access_token) {
  return { json: { mailbox_fail: t.error === 'invalid_grant' ? 'sign_in' : 'token_failed' } };
}
const m = prev.mail || {};
const one = (s) => String(s == null ? '' : s).replace(/[\r\n]+/g, ' ').trim();
const addr = (s) => { const a = one(s).toLowerCase(); return /^[^@\s,;<>"]+@[^@\s,;<>"]+\.[^@\s,;<>"]+$/.test(a) ? a : null; };
const to = addr(m.to), from = addr(m.from), replyTo = addr(m.reply_to);
if (!to || !from) return { json: { mailbox_fail: 'token_failed' } };

if (plan.provider === 'outlook') {
  const message = { subject: one(m.subject).slice(0, 300), body: { contentType: 'HTML', content: String(m.html || '') }, toRecipients: [{ emailAddress: { address: to } }] };
  if (replyTo) message.replyTo = [{ emailAddress: { address: replyTo } }];
  return { json: { mailbox_fail: null, access_token: t.access_token, request: { url: 'https://graph.microsoft.com/v1.0/me/sendMail', body: { message, saveToSentItems: true } } } };
}

const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const word = (s) => (/^[\x20-\x7e]*$/.test(s) ? s : '=?UTF-8?B?' + b64(s) + '?=');
const wrap = (s) => s.replace(/.{1,76}/g, '$&\r\n');
const name = one(m.from_name).replace(/["<>\\]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80);
const boundary = 'zella_voice_' + String(prev.message_id || 'x').replace(/[^0-9a-z]/gi, '').slice(0, 40);
const headers = [
  'From: ' + (name ? (/^[\x20-\x7e]*$/.test(name) ? '"' + name + '"' : word(name)) + ' <' + from + '>' : from),
  'To: ' + to,
  ...(replyTo ? ['Reply-To: ' + replyTo] : []),
  'Subject: ' + word(one(m.subject).slice(0, 300)),
  ...(typeof m.unsubscribe_url === 'string' && /^https:\/\/[^\s<>]+$/.test(m.unsubscribe_url) ? ['List-Unsubscribe: <' + m.unsubscribe_url + '>'] : []),
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + boundary + '"',
];
const mime = headers.join('\r\n') + '\r\n\r\n'
  + '--' + boundary + '\r\nContent-Type: text/plain; charset="UTF-8"\r\nContent-Transfer-Encoding: base64\r\n\r\n' + wrap(b64(m.text || ''))
  + '--' + boundary + '\r\nContent-Type: text/html; charset="UTF-8"\r\nContent-Transfer-Encoding: base64\r\n\r\n' + wrap(b64(m.html || ''))
  + '--' + boundary + '--\r\n';
const raw = b64(mime).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return { json: { mailbox_fail: null, access_token: t.access_token, request: { url: 'https://gmail.googleapis.com/gmail/v1/users/me/messages/send', body: { raw } } } };
